// Emits AnkiTemplates.kt from the goldens generated by generate-goldens.mjs, so the note type's
// CSS and card templates are copied from the web extension rather than re-transcribed by hand.
//
// Run: node tools/generate-templates.mjs

import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const goldens = JSON.parse(
  readFileSync(resolve(here, "../app/src/test/resources/goldens.json"), "utf8")
);
const c = goldens.constants;

const raw = (value) => {
  if (value.includes('"""')) throw new Error("cannot inline a triple-quoted Kotlin string");
  return `"""${value.replaceAll("$", "\${'$'}")}"""`;
};


const kotlin = `package com.lingodeck.reader.anki

/**
 * GENERATED FILE - do not edit.
 *
 * Source: tools/generate-templates.mjs, which copies these strings out of the LingoDeck Chrome
 * extension's extension/src/anki.js. Keeping them identical is what lets a card saved from the
 * phone look exactly like a card saved from the browser, and lets both land on one note.
 */
object AnkiTemplates {
    const val MODEL_NAME = ${raw(c.ANKI_MODEL)}
    const val CARD_TEMPLATE_NAME = ${raw(c.ANKI_CARD_TEMPLATE)}

    val FIELDS: List<String> = listOf(
${c.ANKI_FIELDS.map((f) => `        "${f}"`).join(",\n")},
    )

    val MODEL_CSS: String = ${raw(c.MODEL_CSS)}

    val FRONT_TEMPLATE: String = ${raw(c.FRONT_TEMPLATE)}

    val BACK_TEMPLATE: String = ${raw(c.BACK_TEMPLATE)}
}
`;

const out = resolve(here, "../app/src/main/java/com/lingodeck/reader/anki/AnkiTemplates.kt");
mkdirSync(dirname(out), { recursive: true });
writeFileSync(out, kotlin);
console.log("wrote", out);
